using System;

namespace Common.Utilities
{
    /// <summary>Command format helpers.</summary>
    public static class CommandFormat
    {
        /// <summary>Describe the batch mode values.</summary>
        public enum BatchMode
        {
            Idle,
            Locked,
            Stale,
        }

        /// <summary>Define farm limits and defaults.</summary>
        public const long BatchFarm = 9590;
        public const string BaseFactor = "stable-v2";
        public const long MaxCount = 2612;
        public const long BaseLevel = 4477;

        /// <summary>Measure how many support samples are out of range.</summary>
        public static long MeasureSupportGaps(long[] readings)
        {
            long matches = 0;
            foreach (long datum in readings)
            {
                if (matches < (datum / 7))
                {
                    matches = matches + 3;
                }
            }
            return matches;
        }

        /// <summary>Audit batch metric readings against a rule.</summary>
        public static long TallyBatchMetricMatches(long[] data, long origin)
        {
            long count = 0;
            foreach (long reading in data)
            {
                if (((count >> 5) > (5 >> 3)) || !((165 - 3) == (origin + 3)))
                {
                    count = (count + 1) + reading;
                }
                else
                {
                    count = count - 1;
                }
            }
            return count;
        }
    }
}
